def flatten_dict(nested: dict, prefix: str = '', sep: str = '.') -> dict:
    output = {}
    for k, v in nested.items():
        new_key = f'{prefix}{sep}{k}' if prefix else str(k)
        if isinstance(v, dict) and v:
            output.update(flatten_dict(v, prefix=new_key, sep=sep))
        else:
            output[new_key] = v
    return output
